/// <summary>
/// PricingAttribute of table <c>DlvMode</c> field DlvMode from <c>SaelsLine</c>.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::SalesLine, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(DlvMode, MarkupGroup))]
internal class GUPPricingAttributeDlvModeSalesLineDlvModeGroup extends GUPPricingAttributeDlvMode implements GUPIPricingAttribute
{
}

Method.Source:
protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
{
    QueryBuildDataSource qbdsRoot, qbdsDlvMode;

    if (_qbdsMap && _qbdsMap.exists(tableStr(SalesLine)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(SalesLine));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(SalesLine));

        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(SalesLine), qbdsRoot);
        }
    }

    if (_qbdsMap && _qbdsMap.exists(tableStr(DlvMode)))
    {
        qbdsDlvMode = _qbdsMap.lookup(tableStr(DlvMode));
    }
    else
    {
        qbdsDlvMode = qbdsRoot.addDataSource(tableNum(DlvMode));
        qbdsDlvMode.addLink(fieldNum(SalesLine, DlvMode), fieldNum(DlvMode, Code));
        qbdsDlvMode.joinMode(JoinMode::ExistsJoin);

        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(DlvMode), qbdsDlvMode);
        }
    }

    return qbdsDlvMode;
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
    this.setQueryBuildDatasourceRange(qbds, _value);

    return _query;
}

public GUPPricingAttributeTableFieldPath getPath()
{
    return strFmt('%1#%2_%3$%4#%5',
        tableStr(SalesLine),
        tableStr(DlvMode),
        fieldStr(SalesLine, DlvMode),
        fieldStr(DlvMode, Code),
        this.getAttributeFieldIdentifier());
}
